import React, { createContext, useContext, useState, useEffect } from 'react';
import axios from 'axios';

// Create the Permission Context
const PermissionContext = createContext({
  roles: [],
  permissions: [],
  department: null,
  user: null,
  loading: true,
  hasPermission: (permission) => false,
  hasRole: (role) => false,
  refreshPermissions: () => {},
  setAuthData: (data) => {},
  clearAuthData: () => {},
});

// Custom hook to use the Permission Context
export const usePermission = () => {
  const context = useContext(PermissionContext);
  if (!context) {
    throw new Error('usePermission must be used within a PermissionProvider');
  }
  return context;
};

// Permission Provider Component
export const PermissionProvider = ({ children }) => {
  const [roles, setRoles] = useState([]);
  const [permissions, setPermissions] = useState([]);
  const [department, setDepartment] = useState(null);
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  // Function to check if user has a specific permission
  const hasPermission = (permission) => {
    if (!permission) return true;
    return permissions.includes(permission);
  };

  // Function to check if user has a specific role
  const hasRole = (role) => {
    if (!role) return true;
    return roles.includes(role);
  };

  // Function to set authentication data from login response
  const setAuthData = (data) => {
    const { roles: userRoles = [], permissions: userPermissions = [], department: userDepartment = null, user_id, email } = data;

    setRoles(userRoles);
    setPermissions(userPermissions);
    setDepartment(userDepartment);
    setUser({ id: user_id, email });

    // Store in localStorage for persistence
    localStorage.setItem('userRoles', JSON.stringify(userRoles));
    localStorage.setItem('userPermissions', JSON.stringify(userPermissions));
    localStorage.setItem('userDepartment', userDepartment || '');
    localStorage.setItem('userId', user_id);
    localStorage.setItem('userEmail', email);

    setLoading(false);
  };

  // Function to clear authentication data on logout
  const clearAuthData = () => {
    setRoles([]);
    setPermissions([]);
    setDepartment(null);
    setUser(null);

    // Clear from localStorage
    localStorage.removeItem('userRoles');
    localStorage.removeItem('userPermissions');
    localStorage.removeItem('userDepartment');
    localStorage.removeItem('userId');
    localStorage.removeItem('userEmail');
    localStorage.removeItem('authToken');

    // Clear axios default header
    delete axios.defaults.headers.common['Authorization'];
  };

  // Function to refresh permissions from the backend
  const refreshPermissions = async () => {
    const token = localStorage.getItem('authToken');

    if (!token) {
      setLoading(false);
      return;
    }

    try {
      // Set authorization header
      axios.defaults.headers.common['Authorization'] = `Token ${token}`;

      // Call /api/auth/me/ to get current user data
      const response = await axios.get('http://127.0.0.1:8000/api/auth/me/');

      const { user: userData, roles: userRoles, permissions: userPermissions, profile } = response.data;

      setRoles(userRoles);
      setPermissions(userPermissions);
      setDepartment(profile?.department || null);
      setUser({
        id: userData.id,
        email: userData.email,
        username: userData.username,
        firstName: userData.first_name,
        lastName: userData.last_name,
      });

      // Update localStorage
      localStorage.setItem('userRoles', JSON.stringify(userRoles));
      localStorage.setItem('userPermissions', JSON.stringify(userPermissions));
      localStorage.setItem('userDepartment', profile?.department || '');
      localStorage.setItem('userId', userData.id);
      localStorage.setItem('userEmail', userData.email);

    } catch (error) {
      console.error('Failed to refresh permissions:', error);

      // If token is invalid, clear auth data
      if (error.response && error.response.status === 401) {
        clearAuthData();
      }
    } finally {
      setLoading(false);
    }
  };

  // Load permissions from localStorage on mount and refresh from backend
  useEffect(() => {
    const token = localStorage.getItem('authToken');

    if (token) {
      // Load from localStorage first for immediate access
      const storedRoles = localStorage.getItem('userRoles');
      const storedPermissions = localStorage.getItem('userPermissions');
      const storedDepartment = localStorage.getItem('userDepartment');
      const storedUserId = localStorage.getItem('userId');
      const storedUserEmail = localStorage.getItem('userEmail');

      if (storedRoles) setRoles(JSON.parse(storedRoles));
      if (storedPermissions) setPermissions(JSON.parse(storedPermissions));
      if (storedDepartment) setDepartment(storedDepartment);
      if (storedUserId && storedUserEmail) {
        setUser({ id: parseInt(storedUserId), email: storedUserEmail });
      }

      // Then refresh from backend to ensure data is up-to-date
      refreshPermissions();
    } else {
      setLoading(false);
    }
  }, []);

  const value = {
    roles,
    permissions,
    department,
    user,
    loading,
    hasPermission,
    hasRole,
    refreshPermissions,
    setAuthData,
    clearAuthData,
  };

  return (
    <PermissionContext.Provider value={value}>
      {children}
    </PermissionContext.Provider>
  );
};

export default PermissionContext;
